package nl.voetbalhub.app;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.graphics.Bitmap;import android.widget.*;import org.json.*;
/** Official API/oEmbed catalogue; a separate player window preserves the list and its position. */
public final class VideoShelf40 extends FrameLayout {
 private final Activity a;private final LinearLayout list;private final ScrollView scroll;private boolean attached,loading;private JSONObject snapshot;private YoutubePlayerView video;
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newFixedThreadPool(2);
 private static final android.util.LruCache<String,Bitmap> THUMBS=new android.util.LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getByteCount();}};
 private int dp(float n){return PremiumDesign40.dp(a,n);}
 public VideoShelf40(Activity a){super(a);this.a=a;setBackgroundColor(PremiumDesign40.INK);scroll=new ScrollView(a);list=new LinearLayout(a);list.setOrientation(1);list.setPadding(dp(16),dp(14),dp(16),dp(28));scroll.addView(list);addView(scroll,new LayoutParams(-1,-1));try{snapshot=new JSONObject(a.getSharedPreferences("video43",0).getString("snapshot","{}"));}catch(Exception ignored){}if(!valid(snapshot))try(java.io.InputStream in=a.getAssets().open("youtube-catalog43.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);snapshot=new JSONObject(out.toString("UTF-8"));}catch(Exception ignored){}render();}
 private boolean valid(JSONObject d){try{return d!=null&&d.optInt("schemaVersion")==43&&d.optJSONArray("videos")!=null&&java.time.Instant.parse(d.getString("expiresAt")).toEpochMilli()>System.currentTimeMillis();}catch(Exception e){return false;}}
 private void load(){if(loading||!attached)return;loading=true;render();IO.execute(()->{JSONObject data=null;try{JSONObject r=new JSONObject(DeadlineHttp.get("https://voetbalhub-redactie.onrender.com/integrations/videos43",12000,500000));if(valid(r))data=r;}catch(Exception ignored){}final JSONObject result=data;a.runOnUiThread(()->{loading=false;if(!attached)return;if(result!=null){snapshot=result;a.getSharedPreferences("video43",0).edit().putString("snapshot",result.toString()).apply();}render();});});}
 private void open(String url){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(a,"Geen YouTube-app of browser beschikbaar",Toast.LENGTH_SHORT).show();}}
 private void thumb(ImageView image,String id){Bitmap cached=THUMBS.get(id);if(cached!=null){image.setImageBitmap(cached);return;}IO.execute(()->{Bitmap bitmap=null;java.net.HttpURLConnection c=null;try{for(String quality:new String[]{"maxresdefault","hqdefault"}){c=(java.net.HttpURLConnection)new java.net.URL("https://i.ytimg.com/vi/"+id+"/"+quality+".jpg").openConnection();DeadlineHttp.watch(c,10000);c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);if(c.getResponseCode()==200)try(java.io.InputStream in=c.getInputStream()){bitmap=EditorialBitmap.read(in,1280);}c.disconnect();c=null;if(bitmap!=null)break;}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}final Bitmap result=bitmap;if(result!=null){THUMBS.put(id,result);a.runOnUiThread(()->{if(attached&&image.isAttachedToWindow())image.setImageBitmap(result);});}});}
 private void play(JSONObject v){String id=v.optString("id");if(!v.optBoolean("embeddable")){open("https://www.youtube.com/watch?v="+id);return;}closeVideo();video=new YoutubePlayerView(a,id,v.optString("title"),this::closeVideo);addView(video,new LayoutParams(-1,-1));}
 private void render(){int position=scroll.getScrollY();list.removeAllViews();list.addView(PremiumDesign40.text(a,"SAMENVATTINGEN",25,PremiumDesign40.WHITE,true));list.addView(PremiumDesign40.text(a,"NOS Sport · YouTube",15,PremiumDesign40.GREEN,true));
  list.addView(PremiumDesign40.text(a,"Officiële YouTube-speler. Miniaturen worden door YouTube geladen. Bij afspelen gelden de voorwaarden en privacyregels van YouTube.",12,PremiumDesign40.MUTED,false));
  boolean fresh=valid(snapshot);JSONArray rows=fresh?snapshot.optJSONArray("videos"):null;int count=0;
  if(fresh&&!"available".equals(snapshot.optString("playlistStatus")))list.addView(PremiumDesign40.text(a,"De aangeleverde afspeellijst is niet geverifieerd. Hieronder staan geselecteerde NOS Sport-archiefvideo’s.",12,PremiumDesign40.MUTED,false));
  if(rows!=null)for(int i=0;i<rows.length()&&count<30;i++){JSONObject v=rows.optJSONObject(i);if(v==null||!v.optString("id").matches("[A-Za-z0-9_-]{11}")||!"NOS Sport".equals(v.optString("channel")))continue;final String id=v.optString("id");final JSONObject chosen=v;LinearLayout card=new LinearLayout(a);card.setOrientation(1);PremiumDesign40.card(card,PremiumDesign40.EDGE);
   ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setAdjustViewBounds(false);image.setContentDescription("YouTube-miniatuur: "+v.optString("title"));card.addView(image,new LinearLayout.LayoutParams(-1,dp(182)));thumb(image,id);
   TextView title=PremiumDesign40.text(a,"▶  "+v.optString("title"),17,PremiumDesign40.WHITE,true);title.setPadding(dp(14),dp(12),dp(14),dp(8));card.addView(title);
   String date=v.optString("publishedAt","");if(date.equals("null"))date="";if(date.length()>=10)date=date.substring(0,10);
   TextView meta=PremiumDesign40.text(a,"NOS Sport · YouTube"+(date.isEmpty()?"":" · "+date)+(v.optBoolean("archive")?" · Archief":""),11,PremiumDesign40.MUTED,false);meta.setPadding(dp(14),0,dp(14),dp(8));card.addView(meta);
   TextView source=PremiumDesign40.text(a,"Deze video bekijken op YouTube ↗",12,PremiumDesign40.GREEN,true);source.setPadding(dp(14),dp(10),dp(14),dp(14));source.setFocusable(true);source.setOnClickListener(x->open("https://www.youtube.com/watch?v="+id));card.addView(source);card.setContentDescription("Video afspelen: "+id);card.setOnClickListener(x->play(chosen));PremiumDesign40.touch(card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(16);list.addView(card,lp);count++;}
  TextView state=PremiumDesign40.text(a,loading?"Samenvattingen bijwerken…":count==0?"Geen actueel gecontroleerde videolijst beschikbaar. Bekijk NOS Sport op YouTube.":"Bij afspeelbeperkingen kun je de originele video op YouTube openen.",13,PremiumDesign40.MUTED,false);state.setPadding(0,dp(18),0,dp(12));list.addView(state);
  Button playlist=new Button(a);playlist.setText("Aangeleverde afspeellijst op YouTube ↗");playlist.setOnClickListener(x->open("https://www.youtube.com/playlist?list=PLNykxTr12Azs"));PremiumDesign40.polish(playlist);list.addView(playlist);
  Button channel=new Button(a);channel.setText("NOS Sport op YouTube openen ↗");channel.setOnClickListener(x->open("https://www.youtube.com/@nossport"));PremiumDesign40.polish(channel);list.addView(channel);Button retry=new Button(a);retry.setText(loading?"Bezig met laden…":"Vernieuwen");retry.setEnabled(!loading);retry.setOnClickListener(x->load());PremiumDesign40.polish(retry);list.addView(retry);scroll.post(()->scroll.scrollTo(0,position));
 }
 public boolean closeVideo(){if(video==null)return false;YoutubePlayerView old=video;video=null;removeView(old);old.dispose();return true;}
 public void pauseVideo(){if(video!=null)video.pause();}public void resumeVideo(){if(video!=null)video.resume();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;load();}
 @Override protected void onDetachedFromWindow(){attached=false;closeVideo();super.onDetachedFromWindow();}
}
